import os

# Let's explore the gbrain structure to understand the existing schema
gbrain_dir = "/root/gbrain"

# Check for existing knowledge types, schemas, or configuration
for root, dirs, files in os.walk(gbrain_dir):
    # Skip node_modules and .git
    if '.git' in root or 'node_modules' in root:
        continue

    # Look for key config files
    for f in files:
        if f in ['gbrain.yml', 'package.json', '.env']:
            filepath = os.path.join(root, f)
            try:
                with open(filepath, 'r') as fh:
                    content = fh.read()
                    # Print first 200 chars
                    print(f"{filepath}: {content[:200]}")
            except:
                pass

    # Stop after first level to avoid too much output
    break"}

